---
id: SCR-011   kind: screen   name: Class Editor
app: APP-001   module: MOD-004   screen_type: form   surface: phone
roles: [ROL-003, ROL-004]
tiers: {purpose: default, regions: default, actions: default, states: default}
provenance: ["compass:SCR-011", "model:spec.scrn", "user:FTR-005"]
stories: [US-S005]
---
purpose: Authorized studio users create or update scheduled class details.
route: {name: class_editor, path: /class_editor, params: [], guard: [signed_in, role_has_access]}
reached_from: [SCR-010.open_class_editor]   leads_to: [SCR-012]
role_conditions: what each role sees and may do here differs; the access rows in the closure say how
regions:   # alphabetical by key; the order carries no meaning
  - {key: details, shape: inputs, what: the details the user gives about the class, bind: [ENT-001.title, ENT-001.starts_at, ENT-001.ends_at, ENT-001.instructor_name], importance: primary}
actions:
  - {key: cancel, importance: secondary, intent: cancel, what: leave without saving, effect: [stay]}
  - {key: save, importance: primary, intent: confirm, what: save the new class, precondition: the required details are given, effect: [call OP-S003, go SCR-012], errors: [network, forbidden, validation_failed, conflict], flags: [idempotent]}
inputs:
  - {key: ends_at, type: date, required: True, source: ENT-001.ends_at}
  - {key: instructor_name, type: text, required: True, source: ENT-001.instructor_name}
  - {key: starts_at, type: date, required: True, source: ENT-001.starts_at}
  - {key: title, type: text, required: True, source: ENT-001.title}
states:   # what each must communicate, not how
  - {kind: "domain:conflict", message: The data changed elsewhere since it was loaded; show what changed and let the user choose.}
  - {kind: "domain:submitting", message: The form is being sent; it cannot be sent again meanwhile.}
  - {kind: "domain:validating", message: The input is being checked; the user can keep typing.}
  - {kind: "domain:validation_failed", message: A value breaks a rule; the message names the input and the rule.}
  - {kind: error, message: Something failed; say what happened in plain words and offer a retry.}
  - {kind: forbidden, message: The user's role may not see or do this; say so and where to go instead.}
  - {kind: loading, message: Nothing to show yet; the user must still see that content is coming.}
  - {kind: offline, message: "There is no network; show saved data, and say which actions are unavailable and why."}
  - {kind: success, message: What the user did worked; say what changed.}
copy_keys: [lib.common.error, lib.common.forbidden, lib.common.loading, lib.common.offline, lib.common.success, lib.form.domain.conflict, lib.form.domain.submitting, lib.form.domain.validating, lib.form.domain.validation_failed, scr_011.cancel, scr_011.details_label, scr_011.ends_at, scr_011.instructor_name, scr_011.save, scr_011.starts_at, scr_011.title]
analytics: [class_confirmed]
accessibility: the result of save the new class is announced to assistive technology
acceptance:
  - GIVEN the user has typical data and a working network WHEN the user uses Class Editor for its main purpose THEN the main purpose is achieved and the result is confirmed in plain words
  - GIVEN the user gave a value that breaks a rule on Class Editor WHEN the user submits or leaves the input THEN the problem is named next to the input in plain words, the input is kept, and nothing is sent
  - GIVEN the server fails when Class Editor asks for data or sends a change WHEN the failure is received THEN the user is told in plain words that something went wrong, nothing is lost, and a retry is offered
  - GIVEN a signed-in studio owner on Class Editor WHEN they save the new class THEN the change is saved and the person reaches SCR-012
mock: {profiles: [broken, typical], hero: ["ENT-001:cancelled", "ENT-001:scheduled"]}
